import numpy as np

def td_targets(rewards, next_values, terminated, truncated, gamma):
    r, v = np.asarray(rewards, float), np.asarray(next_values, float)
    term = np.asarray(terminated, bool)
    return (r + gamma * (~term) * v).tolist()
